attempts.sql:
SELECT CASE WHEN total_females = 0 THEN 0.0 ELSE 100.0 * abnormal_females / total_females END AS percentage
FROM (
  SELECT
    SUM(CASE WHEN p.SEX = 'F' THEN 1 ELSE 0 END) AS total_females,
    SUM(CASE WHEN p.SEX = 'F' AND EXISTS (
      SELECT 1 FROM Laboratory l WHERE l.ID = p.ID AND l.PT >= 14
    ) THEN 1 ELSE 0 END) AS abnormal_females
  FROM Patient p
  WHERE (CAST(strftime('%Y', current_timestamp) AS INTEGER) - CAST(strftime('%Y', p.Birthday) AS INTEGER)) > 55
) t;

SELECT CASE WHEN tested_females = 0 THEN 0.0 ELSE 100.0 * abnormal_females / tested_females END AS percentage
FROM (
  SELECT
    SUM(CASE WHEN p.SEX = 'F' AND EXISTS (
      SELECT 1 FROM Laboratory l WHERE l.ID = p.ID AND l.PT IS NOT NULL
    ) THEN 1 ELSE 0 END) AS tested_females,
    SUM(CASE WHEN p.SEX = 'F' AND EXISTS (
      SELECT 1 FROM Laboratory l WHERE l.ID = p.ID AND l.PT >= 14
    ) THEN 1 ELSE 0 END) AS abnormal_females
  FROM Patient p
  WHERE (julianday('now') - julianday(p.Birthday)) / 365.25 > 55
) t;

